create table public.christmas_notes (id uuid primary key default gen_random_uuid(), driver_id uuid not null references public.drivers(id) on delete cascade, truck_id uuid references public.trucks(id) on delete set null, dispatcher_id uuid not null, note text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(driver_id)); alter table public.christmas_notes enable row level security; revoke all on public.christmas_notes from anon, authenticated; grant select,insert,update,delete on public.christmas_notes to authenticated; create policy "Admin Christmas notes" on public.christmas_notes for all to authenticated using ((select exists(select 1 from public.user_roles where user_id=auth.uid() and role='admin'))) with check ((select exists(select 1 from public.user_roles where user_id=auth.uid() and role='admin')));